$Core.projectMap = {
    map: null,
    locationInfo: {},
    locationHot: [],
    mapZoom: 14,
	typeMapIcon: {},
    iconsLocation: {},
    arrInfoLocationMarker: [],
    featured_locations: [],
    routeControl: null,
    locationSyntheticAround: {},
    init: function(options) {
        $Core.projectMap.locationInfo = options.locationInfo;
        $Core.projectMap.locationHot = options.locationHot || [];
        $Core.projectMap.mapZoom = options.mapZoom || 14;
        $Core.projectMap.iconsLocation = $Core.projectMap.getIconDefault();
        $Core.projectMap.typeMapIcon = {
			highlight: $Core.projectMap.iconsLocation.highlight,
			hospital: $Core.projectMap.iconsLocation.hospital,
			university: $Core.projectMap.iconsLocation.university,
			market: $Core.projectMap.iconsLocation.market,
			airport: $Core.projectMap.iconsLocation.airport,
			entertainment: $Core.projectMap.iconsLocation.entertainment
        };
        $Core.projectMap.map = $Core.projectMap.initMapleaf('map-detail', $Core.projectMap.locationInfo, 'cartocdn', false, [], $Core.projectMap.mapZoom);
        $Core.projectMap.addCenterMarker();
        $Core.projectMap.bindMenuEvents();
        $('.btn-center').click(() => {
            $Core.projectMap.map.setView([$Core.projectMap.locationInfo.lat, $Core.projectMap.locationInfo.lng], $Core.projectMap.mapZoom);
        });
        $('.menu-location .item-menu:first-child .btn-action-map').trigger('click');
    }, initMapleaf: (idEl, location, theme = 'openstreetmap', getLocationAround = true, locationsDefault = [], zoom = 14) => {
		var locationInfo = location;
        // set view
        var map = L.map(idEl, {scrollWheelZoom: true}).setView([locationInfo.lat, locationInfo.lng], zoom);
        let urlTheme = '';
        if (theme == 'openstreetmap') {
            urlTheme = 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
        } else if (theme == 'cartocdn') {
            urlTheme = 'https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png';
        } else {
            urlTheme = 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
        }
        // set nền
        L.tileLayer(urlTheme).addTo(map);
		// this.ctrlZoom(map);
        return map;
	}, getIconDefault: (object = '', url = '') => {
        const icons = {
            center: L.icon({
//                iconUrl: 'https://cdn-icons-png.flaticon.com/512/684/684908.png',
                iconUrl: '/images/Icons/icon_map_house.png',
                iconSize: [40, 40], 
                iconAnchor: [10, 20], 
                popupAnchor: [0, -30]
            }),
            hospital: L.icon({
                iconUrl: '/images/Icons/hospital_map.png',
                iconSize: [40, 40], 
                iconAnchor: [20, 40], 
                popupAnchor: [0, -40]
            }),
            airport: L.icon({
                iconUrl: '/images/Icons/airport.png',
                iconSize: [40, 40], 
                iconAnchor: [20, 40], 
                popupAnchor: [0, -40]
            }),
            university: L.icon({
                iconUrl: '/images/Icons/university.png',
                iconSize: [40, 40], 
                iconAnchor: [20, 40], 
                popupAnchor: [0, -40]
            }),
            market: L.icon({
                iconUrl: '/images/Icons/shopping-area.png',
                iconSize: [40, 40], 
                iconAnchor: [20, 40], 
                popupAnchor: [0, -40]
            }),
            highlight: L.icon({
                iconUrl: '/images/Icons/favorite.png',
                iconSize: [40, 40], 
                iconAnchor: [20, 40], 
                popupAnchor: [0, -40]
            }),
            entertainment: L.icon({
                iconUrl: '/images/Icons/entertainment.png',
                iconSize: [40, 40], 
                iconAnchor: [20, 40], 
                popupAnchor: [0, -40]
            }),
			customByUrl: L.icon({
                iconUrl: url,
                iconSize: [40, 40], 
                iconAnchor: [20, 40], 
                popupAnchor: [0, -40]
            })
        };
        if(object.length > 0) {
            return icons[object];
        } else {
            return icons;
        }
    }, addCenterMarker: () => {
        let iconsLocationCenter = $Core.projectMap.getIconDefault('center');
        let marker = L.marker([$Core.projectMap.locationInfo.lat, $Core.projectMap.locationInfo.lng], {icon: iconsLocationCenter}).addTo($Core.projectMap.map);
        let htmlDefault = `<div class="custom-tooltip">
            <div class="tooltip-title fs-14 text-upper fw-bold">${$Core.projectMap.locationInfo.label}</div>
        </div>`;
        marker.bindTooltip(htmlDefault, {
            permanent: true,
            direction: "top",
            offset: [0, -15],
            className: "leaflet-tooltip-custom"
        }).openTooltip();
    }, bindMenuEvents: () => {
        let self = $Core.projectMap;
        $('.btn-block').on('click', function() {
			$(".map_block").removeClass("d-none");
			$(".map_location").addClass("d-none");
			$('.item-menu').removeClass('active');
            $(this).parents('.item-menu').addClass('active');
			$Core.projectMapView.init({
				locationInfos: JSON.parse($location_block),
				mapZoom: $map_zoom,
				box_map_id: "map",
			});
		});
        $('.btn-action-map:not(.btn-block)').on('click', function() {			
			$(".map_location").removeClass("d-none");
			$(".map_block").addClass("d-none");
            self.map.setZoom(self.mapZoom);
            self.map.setView([self.locationInfo.lat, self.locationInfo.lng], self.mapZoom);
            let type = $(this).attr('data-type');
            let routerEl = $('.box-router').find('.router');
            let titleMenu = $(this).text().trim();
            if (self.routeControl) {
                self.map.removeControl(self.routeControl);
            }
            $('.item-menu').removeClass('active');
            $(this).parents('.item-menu').addClass('active');
            if (self.arrInfoLocationMarker && self.arrInfoLocationMarker.length > 0) {
                self.arrInfoLocationMarker.forEach(function(el) {
                    self.map.removeLayer(el);
                });
            }
            self.arrInfoLocationMarker = [];
            routerEl.html('');
            $.ajax({
                url: '/index.php?mod=ajax&act=nearByType',
                method: 'POST',
                data: {type: type, project_id: $('#map-detail').data('id') },
                beforeSend: function() {
                    $Core.util.toggleIndicatior(1);
                },
                success: function(res) {
                    let htmlLocation = '';
                    if (res.length > 0) {
                        res = JSON.parse(res);
                        if (res.status == '200' && res.data) {
							self.featured_locations = typeof res.location_feature != 'undefined' ? res.location_feature : [];
                            self.locationSyntheticAround[type] = res.data;
                            let arrInfoLocationUse = res.data;
                            arrInfoLocationUse.forEach(function(el, idx) {
                                if (el.distance > 0) {
                                    let latlng = JSON.stringify(el.latlng);
                                    htmlLocation += ` <li class="item-router d-flex" data-name="${el.name}" data-type-group="${type}" data-location='${latlng}' data-marker-index="${idx}">
                                        <div class="item-location">
                                            <div class="group-info-location d-flex flex-column">
                                                <b class="title-location mb-0">${el.name}</b>
                                                <span>${el.address}</span>
                                            </div>
                                            <div class="group-info align-items-center">
                                                <b>${el.distance}km</b>
                                            </div>
                                        </div>
                                    </li>`;
                                }
                                let marker = L.marker(el['latlng'], {icon: self.typeMapIcon[type]}).addTo(self.map)
                                    .bindPopup(`<b>${el.name}</b><br><i>Hãy click vào để xem đường đi</i>`);
                                marker.name = el.name;
                                 marker.on('mouseover', function () {
                                    this.openPopup();
                                });
                                marker.on('mouseout', function () {
                                    this.closePopup();
                                });
                                marker.on('click', function() {
                                    if (self.routeControl) {
                                        self.map.removeControl(self.routeControl);
                                    }
                                    self.rawStreet(el['latlng'], 'red', marker, {name: el.name});
                                });
                                self.arrInfoLocationMarker.push(marker);
                            });
                        }
                    }
                    routerEl.html(htmlLocation);
                    self.bindRouterEvents();
                }, complete: function() {
                    $Core.util.toggleIndicatior(0);
                    $('.title-location').find('h3').text(titleMenu);
                }
            });
        });
    }, bindRouterEvents: () => {
        let self = $Core.projectMap;
        $('body').off('click', '.item-router').on('click', '.item-router', function() {
            let dataLocation = $(this).attr('data-location');
            let idx = $(this).attr('data-marker-index');
            let type = $(this).attr('data-type-group');
            let location = JSON.parse(dataLocation);
            let name = $(this).attr('data-name');
            $('.router').find('.item-router').removeClass('active');
            $(this).addClass('active');
            if (self.routeControl) {
                self.map.removeControl(self.routeControl);
            }
            if (typeof self.arrInfoLocationMarker[idx] != 'undefined') {
                self.rawStreet(location, 'red', self.arrInfoLocationMarker[idx], {name: name});
            }
            window.location.href = "#map-detail";
        });
    }, rawStreet: (location, color = 'red', marker, data = {}) => {
        let self = $Core.projectMap;
        $Core.util.toggleIndicatior(1);
        self.routeControl = L.Routing.control({
            waypoints: [
                L.latLng([self.locationInfo.lat, self.locationInfo.lng]),
                L.latLng(location)
            ],
            routeWhileDragging: false,
            show: false,
            createMarker: () => null,
            fitSelectedRoutes: true,
            lineOptions: {
                styles: [{color: color, opacity: 0.8, weight: 6}]
            }
        }).addTo(self.map);
        self.routeControl.on('routesfound', function (e) {
            $Core.util.toggleIndicatior(0);
            const summary = e.routes[0].summary;
            const distanceKm = (summary.totalDistance / 1000).toFixed(2);
            const timeMin = Math.round(summary.totalTime / 60);
            let htmlInfoExtensions = `<b>${data.name}</b><br> <span>Quãng đường: ${distanceKm}km</span> <br> <span>Thời gian: ${timeMin} phút</span>`;
            marker.bindPopup(htmlInfoExtensions);
            marker.openPopup();
        });
    }, submitSearchLocation: (_this, e) => {
        e.preventDefault();
        let self = $Core.projectMap;
        let value = $(_this).parent('.group-search-location').find('.js-location-keyword').val().trim();
        let radius = $(_this).data('radius');
        let routerEl = $('.box-router').find('.router');
        let project_id = $('#map-detail').data('id');
        if (this.oldKeywordSearchLocation != value) {
            this.oldKeywordSearchLocation = value;
            if (value.length > 0) {
                if (self.routeControl) {
                    self.map.removeControl(self.routeControl);
                }
                if (self.arrInfoLocationMarker && self.arrInfoLocationMarker.length > 0) {
                    self.arrInfoLocationMarker.forEach(function(el) {
                        self.map.removeLayer(el);
                    });
                }
                routerEl.html('');
                let keyCacheData = '_cache_'+value.toLowerCase()+'_'+$Core.projectMap.locationInfo.lat+'_'+$Core.projectMap.locationInfo.lng+'_'+radius;
                if (1==2 && $Core.cache.has(keyCacheData)) {
                    $Core.util.toggleIndicatior(1);
                    let dataCache = $Core.cache.get(keyCacheData);
                    let dataLocation = JSON.parse(dataCache);
                    htmlLocation = $Core.projectMap.bindDataHtmlLocation(dataLocation);
                    routerEl.html(htmlLocation);
                    self.bindRouterEvents();
                    $('.item-menu').removeClass('active');
                    $('.title-location').find('h3').text('Tìm kiếm: "'+value+'"')
                    $Core.util.toggleIndicatior(0);
                } else {
                    console.log('here1');
                    $.ajax({
                        url: PCMS_URL+'/index.php?mod=ajax&act=search_location',
                        method: 'POST',
                        data: {
                            location_keyword: value,
                            lat: $Core.projectMap.locationInfo.lat,
                            lng: $Core.projectMap.locationInfo.lng,
                            radius: radius,
                            project_id: project_id,
                        },
                        dataType: 'json',
                        timeout: 10000,
                        beforeSend: function() {
                            $Core.util.toggleIndicatior(1);
                        }, success: function(respJson) {
                            let status = typeof respJson.status != 'undefined' ? respJson.status : 500;
                            let msg = typeof respJson.msg != 'undefined' ? respJson.msg : 'Có lỗi xảy ra!!!';
                            let data = typeof respJson.data != 'undefined' ? respJson.data : [];
                            let htmlLocation = '';
                            if (status == 200) {
								// $Core.cache.set(keyCacheData, JSON.stringify(data),'local', 60*60*24*30);
                                htmlLocation = $Core.projectMap.bindDataHtmlLocation(data);
                            } else {
								htmlLocation = `<li class="item-router not-location d-flex flex-column align-items-center">
									<img class="image-not-location" width="100" height="100" src="/images/Icons/hide.png">
									<p>Xin lỗi. Không tìm thấy địa điểm</p>
								</li>`;
                            }
                            routerEl.html(htmlLocation);
                            self.bindRouterEvents();
                        }, error: function(xhr, status, error) {
                            if (status === "timeout") {
                                console.log("Quá thời gian request");
                            } else {
                                console.log('Có lỗi xảy ra!!!! => ', error);
                            }
                            this.oldKeywordSearchLocation = '';
                        }, complete: function() {
                            $Core.util.toggleIndicatior(0);
                            $('.item-menu').removeClass('active');
                            $('.title-location').find('h3').text('Tìm kiếm: "'+value+'"')
                        }
                    });
                }
            }
        }
    },
    bindDataHtmlLocation: function(data) {
        let htmlLocation = '';
        let self = $Core.projectMap;
        if (data.length > 0) {
            data.forEach(function(el, idx) {
                let type = el.type;
                let iconsLocationCenter = self.getIconDefault('customByUrl', '/images/Icons/search.png');
                if (el.distance > 0) {
                    let latlng = JSON.stringify(el.latlng);
                    let is_flag = false;
                    if (self.featured_locations.length > 0) {
                        self.featured_locations.forEach(function(elFeature, indexFeature) {
                            if ($Core.projectMap.isSameCoord({lat: elFeature.lat, lng: elFeature.lng}, {lat: el.latlng[0], lng: el.latlng[1]})) {
                                is_flag = true;
                            }
                        });
                    }
                    let iconHot = '';
                    if (typeof profile_id != 'undefined' && profile_id != '0' && 1 == 2) {
                        if (is_flag) {
                            iconHot = `<i class='bx bxs-star btn-star-hot' onClick="$Core.projectMap.clickHotLocation(this, event)" data-location='${latlng}' style="color: #f31414;"></i>`;
                        } else {
                            iconHot = `<i class='bx bx-star btn-star-hot' onClick="$Core.projectMap.clickHotLocation(this, event)" data-location='${latlng}'></i>`;
                        }
                    }
                    htmlLocation += `<li class="item-router d-flex" data-name="${el.name}" data-address="${el.address}" data-type-group="${type}" data-location='${latlng}' data-marker-index="${idx}">
                        <div class="item-location">
                            <div class="group-info-location d-flex flex-column">
                                <b class="title-location mb-0">${el.name}</b>
                                <span>${el.address}</span>
                            </div>
                            <div class="group-info align-items-center">
                                <b>${el.distance}km</b>
                            </div>
                        </div>
                        ${iconHot}
                    </li>`;
                }
                let marker = L.marker(el['latlng'], {icon: iconsLocationCenter}).addTo(self.map)
                    .bindPopup(`<b>${el.name}</b><br><i>Hãy click vào để xem đường đi</i>`);
                marker.name = el.name;
                    marker.on('mouseover', function () {
                    this.openPopup();
                });
                marker.on('mouseout', function () {
                    this.closePopup();
                });
                marker.on('click', function() {
                    if (self.routeControl) {
                        self.map.removeControl(self.routeControl);
                    }
                    self.rawStreet(el['latlng'], 'red', marker, {name: el.name});
                });
                self.arrInfoLocationMarker.push(marker);
            })
        } else {
            htmlLocation = `<li class="item-router not-location d-flex">
				<img class="image-not-location" width="100" height="100" src="/images/Icons/hide.png">
				<p>Xin lỗi. Không tìm thấy địa điểm</p>
			</li>`;
        }
        return htmlLocation;
    },
};
$Core.projectMapView = {
    map: null,
    markers: [],
    locationInfos: [],
    mapZoom: 14,
    defaultWidth: 0,
    init: function(options) {
        $Core.projectMapView.locationInfos = options.locationInfos;
        $Core.projectMapView.mapZoom = options.mapZoom || 14;
        var box_map_id = options.box_map_id || 'map';
        $Core.projectMapView.markers = [];
        $Core.projectMapView.defaultWidth = window.innerWidth;
        $Core.projectMapView.map = $Core.projectMap.initMapleaf(box_map_id, $Core.projectMapView.locationInfos[0], 'cartocdn', false, [], $Core.projectMapView.mapZoom);
        $Core.projectMapView.renderMarkers();
        $Core.projectMapView.bindRouterEvents();
        $Core.projectMapView.bindCollapseEvents();
        $Core.projectMapView.handleResponsive();
        $Core.projectMapView.bindLinkEvents();
    },
    renderMarkers: function() {
        let self = $Core.projectMapView;
        $Core.projectMapView.locationInfos.forEach(function(location, index) {
            let htmlDefault = '';
            let pricePerM2El = '';
            let pricePerM2 = location.price_per_m2;
            let numbers = [];
            let stringPrice = '';
            let elementBox = $('.project-' + location.id);
            let territory = location.territory;
            if (pricePerM2 != null && pricePerM2.toString().length > 0) {
                numbers = pricePerM2.toString().match(/\d+/g);
            }
            if (numbers.length > 0 && numbers[0] != '0') {
                numbers.forEach(function(el, idx) {
                    let sign = idx >= 1 ? ' ~ ' : '';
                    let price = parseFloat(el) / 1000000;
                    stringPrice += sign + price.toString() + 'tr/m2';
                });
            }
			
			project_title = `<div class="fs-12 text-upper fw-bold">${location.label}</div>`;
            if (typeof stringPrice != 'undefined' && stringPrice.toString().length > 0) {
                pricePerM2El = `<div class="tooltip-price">${stringPrice}</div>`;
            }
			htmlDefault = `<div class="custom-tooltip d-flex flex-column gap-1">${project_title} ${pricePerM2El}</div>`;
            let iconsLocation = $Core.projectMap.getIconDefault('center');
            const marker_child = L.marker([location.lat, location.lng], { icon: iconsLocation }).addTo(self.map);
			
			let htmlBox = elementBox.clone();
			htmlBox.removeClass('d-none');
			marker_child.bindPopup(htmlDefault);
            if (territory.length > 0) {
                const polygon = L.polygon(territory, {
                    color: 'red',
                    fillColor: 'red',
                    fillOpacity: 0.3,
                    dashArray: '5, 10'
                }).addTo(self.map);
                // self.map.fitBounds(polygon.getBounds());
				polygon.on('click', (e) => {
				 	marker_child.bindPopup(htmlBox[0]);
                    marker_child.openPopup();
                    marker_child.closeTooltip();
				});
            }
            self.markers.push(marker_child);
            if (elementBox.length > 0) {
				console.log(elementBox);
                let htmlBox = elementBox.clone();
                htmlBox.removeClass('d-none');
                marker_child.bindPopup(htmlDefault);
                if (htmlDefault.length > 0) {
                    marker_child.bindTooltip(htmlDefault, {
                        permanent: true,
                        direction: "top",
                        offset: [10, -20],
                        className: "leaflet-tooltip-custom"
                    }).openTooltip();
                }
                marker_child.on('click', function() {
                    marker_child.bindPopup(htmlBox[0]);
                    this.openPopup();
                    this.closeTooltip();
                });
                marker_child.on('popupclose', function() {
                    this.openTooltip();
                });
            }
        });
    },
    bindRouterEvents: function() {
        let self = $Core.projectMapView;
        $('.router').on('click', '.item-router', function(e) {
            if ($(e.target).closest('a.btn-link', this).length) {
                return;
            }
            let innerWidth = window.innerWidth;
            var idx = $(this).data('index');
            var location = self.locationInfos[idx];
            var marker = self.markers[idx];
            if (marker.length > 0) {
                marker.forEach(function(el) {
                    el.closeTooltip();
                    el.closePopup();
                });
            }
            marker.openTooltip();
            let zoom = $(this).attr('data-map-zoom');
            if (!zoom || zoom.length <= 0) {
                zoom = 14;
            }
            $('.item-router').removeClass('active');
            if (!$(this).hasClass('active')) {
                $(this).addClass('active');
            }
            if (innerWidth <= 1024) {
                if (!$('.box-location').hasClass('collapse-active')) {
                    $('.box-location').addClass('collapse-active');
                }
            }
            if (marker) {
                self.map.setView([location.lat, location.lng], zoom, { animate: true });
            }
        });
    },
    bindCollapseEvents: function() {
        $('.collapse-project').click(function() {
            let parentEl = $(this).parents('.box-location');
            parentEl.toggleClass('collapse-active');
        });
    },
    handleResponsive: function() {
        let self = $Core.projectMapView;
        setInterval(function() {
            let innerWidth = window.innerWidth;
            if (self.defaultWidth != innerWidth) {
                self.defaultWidth = innerWidth;
                if (innerWidth <= 1024) {
                    if (!$('.box-location').hasClass('collapse-active')) {
                        $('.box-location').addClass('collapse-active');
                    }
                } else {
                    if ($('.box-location').hasClass('collapse-active')) {
                        $('.box-location').removeClass('collapse-active');
                    }
                }
            }
        }, 1500);
    },
    bindLinkEvents: function() {
        $('.btn-link').on('click', function(e) {
            let link = $(this);
            let href = link.attr('href');
            if (
                href.startsWith('#') ||
                href.startsWith('javascript:') ||
                link.attr('target') === '_blank' ||
                e.ctrlKey || e.metaKey || e.shiftKey
            ) {
                return;
            }
            $Core.util.toggleIndicatior(1);
            setTimeout(function() {
                if (!document.hidden) {
                    $Core.util.toggleIndicatior(0);
                }
            }, 8000);
        });
    }
};